insert into public.products (id, category_id, name, slug, short_description, description, pricing_unit, base_price_cents, discount_type, discount_value, promo_starts_at, promo_ends_at, min_quantity, max_quantity, min_price_cents, max_price_cents, delivery_days, delivery_label, benefits, audience, includes, faqs, is_active, is_featured, sort_order, product_type, is_new, is_best_seller, download_limit) values ('00000000-0000-4000-8000-000000000201', '00000000-0000-4000-8000-000000000101', 'Modelo de TCC ABNT (Word)', 'modelo-tcc-abnt', 'Modelo de TCC completo e editável em Word, já estruturado segundo as normas ABNT.', 'Um modelo de trabalho acadêmico em formato .docx com todos os elementos pré-textuais, textuais e pós-textuais já configurados conforme a ABNT (NBR 14724, 6023, 10520). Estilos de títulos, sumário automático, numeração de páginas e exemplos de citação incluídos.', 'fixed', 14990, 'sale_price', 9990, null, null, 1, 1, null, null, 0, 'Entrega imediata', '["Economiza horas de configuração de formatação","Sumário e numeração automáticos","Atualizações incluídas"]'::jsonb, '["Graduandos iniciando o TCC","Quem precisa reconfigurar o trabalho nas normas"]'::jsonb, '["Arquivo .docx editável","Guia rápido de uso (PDF)","Exemplos de citação e referência"]'::jsonb, '[{"question":"O modelo escreve o TCC por mim?","answer":"Não. O modelo é uma estrutura pronta e editável para você organizar e escrever o seu próprio conteúdo com a formatação correta."},{"question":"Em qual versão do Word funciona?","answer":"O arquivo .docx abre em Word 2016+, Google Docs e LibreOffice. Recursos de sumário automático funcionam melhor no Word para desktop."}]'::jsonb, true, true, 1, 'digital', false, true, null) on conflict (id) do nothing;
insert into public.products (id, category_id, name, slug, short_description, description, pricing_unit, base_price_cents, discount_type, discount_value, promo_starts_at, promo_ends_at, min_quantity, max_quantity, min_price_cents, max_price_cents, delivery_days, delivery_label, benefits, audience, includes, faqs, is_active, is_featured, sort_order, product_type, is_new, is_best_seller, download_limit) values ('00000000-0000-4000-8000-000000000202', '00000000-0000-4000-8000-000000000102', 'Modelo de Artigo Científico ABNT', 'modelo-artigo-cientifico-abnt', 'Estrutura IMRaD pronta em Word com formatação ABNT e exemplos de citação.', 'Modelo de artigo científico em .docx pronto para preencher: título, resumo, palavras-chave, introdução, método, resultados, discussão e referências, com estilos configurados.', 'fixed', 8990, 'none', 0, null, null, 1, 1, null, null, 0, 'Entrega imediata', '["Estrutura IMRaD pronta","Formatação de referências exemplificada"]'::jsonb, '["Graduandos e pós-graduandos preparando submissão"]'::jsonb, '["Arquivo .docx editável","Exemplos de resumo e palavras-chave"]'::jsonb, '[]'::jsonb, true, true, 2, 'digital', false, false, null) on conflict (id) do nothing;
insert into public.products (id, category_id, name, slug, short_description, description, pricing_unit, base_price_cents, discount_type, discount_value, promo_starts_at, promo_ends_at, min_quantity, max_quantity, min_price_cents, max_price_cents, delivery_days, delivery_label, benefits, audience, includes, faqs, is_active, is_featured, sort_order, product_type, is_new, is_best_seller, download_limit) values ('00000000-0000-4000-8000-000000000203', '00000000-0000-4000-8000-000000000103', 'Guia de Formatação ABNT', 'guia-formatacao-abnt', 'Guia passo a passo para formatar TCC, dissertação e tese nas normas ABNT.', 'E-book com o passo a passo da normalização: margens, fontes, espaçamento, sumário, citações, referências e elementos pré-textuais, com checklists para cada parte.', 'fixed', 5990, 'sale_price', 3990, null, null, 1, 1, null, null, 0, 'Entrega imediata', '["Passo a passo visual com exemplos","Checklists prontos"]'::jsonb, '["Qualquer pessoa formatando um trabalho acadêmico"]'::jsonb, '["E-book (PDF)","Resumo em uma página (PDF)"]'::jsonb, '[{"question":"Cobre a última versão das normas?","answer":"O guia é baseado nas NBR 14724, 6023, 10520, 6024 e 6027 vigentes e recebe atualizações."}]'::jsonb, true, true, 3, 'digital', false, false, null) on conflict (id) do nothing;
insert into public.products (id, category_id, name, slug, short_description, description, pricing_unit, base_price_cents, discount_type, discount_value, promo_starts_at, promo_ends_at, min_quantity, max_quantity, min_price_cents, max_price_cents, delivery_days, delivery_label, benefits, audience, includes, faqs, is_active, is_featured, sort_order, product_type, is_new, is_best_seller, download_limit) values ('00000000-0000-4000-8000-000000000204', '00000000-0000-4000-8000-000000000104', 'Template de Apresentação de TCC', 'template-apresentacao-tcc', 'Template de slides profissional para a defesa do TCC, editável no PowerPoint.', 'Conjunto de slides em .pptx com layout profissional em harmonia com a identidade da marca: capa, sumário, resultados, gráficos e encerramento. Fontes e cores prontas para alterar.', 'fixed', 4990, 'none', 0, null, null, 1, 1, null, null, 0, 'Entrega imediata', '["Layout profissional pronto","Slide de abertura e encerramento"]'::jsonb, '["Graduandos e pós-graduandos na defesa e em seminários"]'::jsonb, '["Arquivo .pptx editável","Roteiro de fala sugerido (PDF)"]'::jsonb, '[]'::jsonb, true, false, 4, 'digital', true, false, null) on conflict (id) do nothing;
insert into public.products (id, category_id, name, slug, short_description, description, pricing_unit, base_price_cents, discount_type, discount_value, promo_starts_at, promo_ends_at, min_quantity, max_quantity, min_price_cents, max_price_cents, delivery_days, delivery_label, benefits, audience, includes, faqs, is_active, is_featured, sort_order, product_type, is_new, is_best_seller, download_limit) values ('00000000-0000-4000-8000-000000000205', '00000000-0000-4000-8000-000000000105', 'Kit Acadêmico · 315 modelos editáveis', 'kit-academico-modelos', 'Pacote com templates para TCC, artigo, projeto, apresentação e documentos acadêmicos.', 'O kit completo de materiais de apoio: modelos de TCC e artigo, projetos de pesquisa, regras de formatação, apresentações, planilhas de cronograma e roteiros de escrita. Um único pacote com os recursos essenciais para a jornada acadêmica.', 'fixed', 19990, 'sale_price', 14990, null, null, 1, 1, null, null, 0, 'Entrega imediata', '["315 modelos organizados em pastas","Um único pacote para toda a graduação"]'::jsonb, '["Graduandos do início ao fim do curso","Pós-graduandos"]'::jsonb, '["Arquivo .zip com os 315 modelos","Sumário do conteúdo (PDF)"]'::jsonb, '[{"question":"Quais formatos estão no kit?","answer":"DOCX, PPTX, XLSX e PDF, organizados por categoria."}]'::jsonb, true, true, 5, 'digital', false, true, null) on conflict (id) do nothing;
insert into public.products (id, category_id, name, slug, short_description, description, pricing_unit, base_price_cents, discount_type, discount_value, promo_starts_at, promo_ends_at, min_quantity, max_quantity, min_price_cents, max_price_cents, delivery_days, delivery_label, benefits, audience, includes, faqs, is_active, is_featured, sort_order, product_type, is_new, is_best_seller, download_limit) values ('00000000-0000-4000-8000-000000000206', '00000000-0000-4000-8000-000000000105', 'Modelo de Projeto de Pesquisa', 'modelo-projeto-de-pesquisa', 'Modelo em Word com as seções de um projeto: problema, objetivos, metodologia e cronograma.', 'Estrutura editável de projeto de pesquisa em .docx, com instruções em cada seção para você preencher o seu próprio projeto com segurança.', 'fixed', 7990, 'percent', 20, null, null, 1, 1, null, null, 0, 'Entrega imediata', '["Seções com instruções no próprio documento"]'::jsonb, '["Quem precisa aprovar um projeto de pesquisa ou TCC"]'::jsonb, '["Arquivo .docx editável","Cronograma em planilha (XLSX)"]'::jsonb, '[]'::jsonb, true, false, 6, 'digital', false, false, null) on conflict (id) do nothing;
insert into public.products (id, category_id, name, slug, short_description, description, pricing_unit, base_price_cents, discount_type, discount_value, promo_starts_at, promo_ends_at, min_quantity, max_quantity, min_price_cents, max_price_cents, delivery_days, delivery_label, benefits, audience, includes, faqs, is_active, is_featured, sort_order, product_type, is_new, is_best_seller, download_limit) values ('00000000-0000-4000-8000-000000000207', '00000000-0000-4000-8000-000000000105', 'Checklist de Revisão de TCC', 'checklist-revisao-tcc', 'Checklist de mais de 80 itens para revisar estrutura, conteúdo e normas antes da entrega.', 'Planilha e lista de verificação para revisar o trabalho antes da entrega: estrutura, coesão, metodologia, normas, referências e apresentação. Ajuda a evitar os erros mais comuns.', 'fixed', 2990, 'none', 0, null, null, 1, 1, null, null, 0, 'Entrega imediata', '["80+ itens organizados por etapa"]'::jsonb, '["Quem está na reta final do TCC"]'::jsonb, '["Planilha de revisão (XLSX)","Versão em PDF para imprimir"]'::jsonb, '[]'::jsonb, true, false, 7, 'digital', true, false, null) on conflict (id) do nothing;
insert into public.products (id, category_id, name, slug, short_description, description, pricing_unit, base_price_cents, discount_type, discount_value, promo_starts_at, promo_ends_at, min_quantity, max_quantity, min_price_cents, max_price_cents, delivery_days, delivery_label, benefits, audience, includes, faqs, is_active, is_featured, sort_order, product_type, is_new, is_best_seller, download_limit) values ('00000000-0000-4000-8000-000000000208', '00000000-0000-4000-8000-000000000106', 'E-book: Como escrever um TCC do zero', 'ebook-como-escrever-tcc-do-zero', 'Roteiro prático de escrita do TCC, do tema à versão final, com método de escrita em etapas.', 'E-book com um método simples para escrever o TCC sem travar: escolha de tema, problema de pesquisa, planejamento de escrita, primeiras versões, revisão e preparação para a defesa.', 'fixed', 6990, 'percent', 15, null, null, 1, 1, null, null, 0, 'Entrega imediata', '["Método de escrita passo a passo","Exemplos práticos"]'::jsonb, '["Quem está começando o TCC","Quem está travado na escrita"]'::jsonb, '["E-book (PDF)","Capa personalizada para leitura em dispositivos"]'::jsonb, '[]'::jsonb, true, false, 8, 'digital', true, false, null) on conflict (id) do nothing;
insert into public.faqs (question, answer, category, sort_order) select 'Como recebo os produtos?', 'Imediatamente. Assim que o pagamento é confirmado, os produtos comprados ficam disponíveis para download na sua conta, em "Meus produtos".', 'pedidos', 1 where not exists (select 1 from public.faqs where question = 'Como recebo os produtos?');
insert into public.faqs (question, answer, category, sort_order) select 'O que está incluso no preço?', 'O arquivo (ou conjunto de arquivos) descrito na página de cada produto. Nada é cobrado depois da compra.', 'produtos', 2 where not exists (select 1 from public.faqs where question = 'O que está incluso no preço?');
insert into public.faqs (question, answer, category, sort_order) select 'Quais formas de pagamento são aceitas?', 'Pix, com confirmação automática, e cartão de crédito, com opção de parcelamento.', 'pagamento', 3 where not exists (select 1 from public.faqs where question = 'Quais formas de pagamento são aceitas?');
insert into public.faqs (question, answer, category, sort_order) select 'Posso baixar mais de uma vez?', 'Sim. Depois de comprado, o produto fica disponível na sua conta para baixar quantas vezes precisar.', 'seguranca', 4 where not exists (select 1 from public.faqs where question = 'Posso baixar mais de uma vez?');
insert into public.faqs (question, answer, category, sort_order) select 'Os materiais substituem o conteúdo que devo produzir?', 'Não. São modelos, guias e recursos de apoio para você estruturar e escrever o seu próprio trabalho com mais segurança e autonomia.', 'produtos', 5 where not exists (select 1 from public.faqs where question = 'Os materiais substituem o conteúdo que devo produzir?');
